"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["4600"],{7272(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>h,frontMatter:()=>r,contentTitle:()=>a,toc:()=>l,assets:()=>c});var s=JSON.parse('{"id":"networks/tcp-advanced","title":"TCP Advanced \u2014 Congestion Control & Performance","description":"TCP\'s congestion control is one of the most important algorithmic achievements in networking. This page traces its evolution from Van Jacobson\'s 1988 crisis fix through BBR\'s modern bandwidth-probing approach.","source":"@site/docs/networks/41-tcp-advanced.md","sourceDirName":"networks","slug":"/networks/tcp-advanced","permalink":"/Mindstack/docs/networks/tcp-advanced","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":41,"frontMatter":{"title":"TCP Advanced \u2014 Congestion Control & Performance","sidebar_label":"TCP Advanced","sidebar_position":41},"sidebar":"networkSidebar","previous":{"title":"TCP Fundamentals","permalink":"/Mindstack/docs/networks/tcp-fundamentals"},"next":{"title":"UDP & QUIC","permalink":"/Mindstack/docs/networks/udp"}}'),i=t(4848),o=t(8453);let r={title:"TCP Advanced \u2014 Congestion Control & Performance",sidebar_label:"TCP Advanced",sidebar_position:41},a="TCP Advanced \u2014 Congestion Control & Performance",c={},l=[{value:"The 1986 Internet Congestion Collapse",id:"the-1986-internet-congestion-collapse",level:2},{value:"Core Congestion Control Concepts",id:"core-congestion-control-concepts",level:2},{value:"TCP Tahoe (Van Jacobson, 1988)",id:"tcp-tahoe-van-jacobson-1988",level:2},{value:"TCP Reno (1990)",id:"tcp-reno-1990",level:2},{value:"TCP NewReno (RFC 3782, 1996-1999)",id:"tcp-newreno-rfc-3782-1996-1999",level:2},{value:"SACK-Based Congestion Control (RFC 2018 + RFC 2883)",id:"sack-based-congestion-control-rfc-2018--rfc-2883",level:2},{value:"TCP CUBIC (RFC 8312, 2008)",id:"tcp-cubic-rfc-8312-2008",level:2},{value:"TCP BBR \u2014 Bottleneck Bandwidth and RTT (Google, 2016)",id:"tcp-bbr--bottleneck-bandwidth-and-rtt-google-2016",level:2},{value:"Bandwidth-Delay Product (BDP)",id:"bandwidth-delay-product-bdp",level:2},{value:"TCP Performance Diagnostics",id:"tcp-performance-diagnostics",level:2},{value:"ECN \u2014 Explicit Congestion Notification (RFC 3168)",id:"ecn--explicit-congestion-notification-rfc-3168",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"tcp-advanced--congestion-control--performance",children:"TCP Advanced \u2014 Congestion Control & Performance"})}),"\n",(0,i.jsx)(n.p,{children:"TCP's congestion control is one of the most important algorithmic achievements in networking. This page traces its evolution from Van Jacobson's 1988 crisis fix through BBR's modern bandwidth-probing approach."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"the-1986-internet-congestion-collapse",children:"The 1986 Internet Congestion Collapse"}),"\n",(0,i.jsx)(n.p,{children:"In October 1986, ARPANET throughput between LBL (Lawrence Berkeley Laboratory) and UC Berkeley dropped from 32 kbps to 40 bps \u2014 a 1000\xd7 reduction. The cause: TCP senders kept retransmitting into an already-congested network, making it worse (a positive feedback loop)."}),"\n",(0,i.jsx)(n.p,{children:"Van Jacobson diagnosed the problem and developed a fix \u2014 published as RFC 1072 (1988) and later RFC 2001 (1996). His algorithms \u2014 slow start, congestion avoidance, fast retransmit, and fast recovery \u2014 became the foundation of all TCP congestion control that followed."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"core-congestion-control-concepts",children:"Core Congestion Control Concepts"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Congestion Window (cwnd):\n  Sender-side limit: sender can have at most min(cwnd, rwnd) bytes in flight\n  Managed by congestion control algorithms (adjusted up/down based on signals)\n\nSender's effective window:\n  send_window = min(congestion_window, receive_window)\n  \u2192 limited by BOTH the network's capacity AND the receiver's buffer\n\nCongestion signals (how TCP detects congestion):\n  1. Packet loss:\n     - Timeout (RTO): segment not ACKed in time \u2192 severe congestion signal\n     - Triple duplicate ACK: out-of-order segments \u2192 mild congestion signal (fast retransmit)\n  2. ECN (Explicit Congestion Notification, RFC 3168):\n     - Network marks packets instead of dropping them\n     - Much earlier signal than actual loss\n\nSlow Start Threshold (ssthresh):\n  Boundary between Slow Start (exponential growth) and Congestion Avoidance (linear growth)\n  Initial value: typically 65535 bytes (or infinity \u2014 up to implementation)\n  Updated when congestion detected\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tcp-tahoe-van-jacobson-1988",children:"TCP Tahoe (Van Jacobson, 1988)"}),"\n",(0,i.jsx)(n.p,{children:"The original congestion control. Named after Lake Tahoe (site of the USENIX conference)."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'Algorithm phases:\n\n1. SLOW START (exponential growth):\n   cwnd starts at 1 MSS\n   Each ACK received: cwnd += 1 MSS\n   \u2192 cwnd doubles every RTT\n   \u2192 NOT actually "slow" \u2014 grows exponentially\n   \u2192 Continues until cwnd \u2265 ssthresh\n\n2. CONGESTION AVOIDANCE (linear growth):\n   cwnd starts at ssthresh\n   Each RTT (approx): cwnd += 1 MSS\n   \u2192 Additive Increase \u2014 probes for more bandwidth cautiously\n   \u2192 Continues until loss detected\n\n3. ON LOSS (any loss \u2014 timeout OR triple dupACK):\n   ssthresh = max(cwnd/2, 2 MSS)   ! save half of cwnd as new threshold\n   cwnd = 1 MSS                     ! back to slow start!\n   Return to phase 1\n\nVisualized (saw-tooth pattern):\ncwnd ^\n     \u2502    /\n     \u2502   /  (slow start)\n     \u2502  /\n     \u2502 /\nssth \u2502.........\n     \u2502        \\ /       (congestion avoidance)\n     \u2502         /\n     \u2502        /\n     1\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u25BA time\n       loss \u2192 reset\n'})}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Tahoe's weakness:"})," Triple dupACK (mild loss) and timeout (catastrophic loss) get the same reaction \u2014 drop to cwnd=1. This is too conservative for dupACK."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tcp-reno-1990",children:"TCP Reno (1990)"}),"\n",(0,i.jsx)(n.p,{children:"Added Fast Recovery \u2014 different response to dupACK vs timeout."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'On triple duplicate ACK (mild loss signal):\n  1. FAST RETRANSMIT: immediately send the missing segment (don\'t wait for RTO)\n  2. FAST RECOVERY:\n     ssthresh = max(cwnd/2, 2 MSS)\n     cwnd = ssthresh + 3 MSS   ! NOT back to 1 \u2014 stay at half capacity\n     \u2192 Each additional dupACK: cwnd += 1 MSS (inflate by dupACKs in flight)\n     \u2192 When new ACK arrives (hole filled): cwnd = ssthresh (deflate)\n     \u2192 Continue in Congestion Avoidance from ssthresh (not Slow Start)\n\nOn TIMEOUT (severe loss signal):\n  Same as Tahoe: ssthresh = cwnd/2; cwnd = 1 MSS; slow start\n\nReno\'s weakness:\n  Only one segment can be recovered per RTT\n  If multiple segments lost: enters Slow Start after partial recovery ("multiple losses")\n  This is called "Reno\'s problem with multiple losses"\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tcp-newreno-rfc-3782-1996-1999",children:"TCP NewReno (RFC 3782, 1996-1999)"}),"\n",(0,i.jsx)(n.p,{children:"Fixed Reno's multiple-loss problem by tracking partial ACKs and retransmitting additional missing segments during Fast Recovery without leaving recovery mode."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"sack-based-congestion-control-rfc-2018--rfc-2883",children:"SACK-Based Congestion Control (RFC 2018 + RFC 2883)"}),"\n",(0,i.jsx)(n.p,{children:"With SACK, the sender knows exactly which segments arrived and which are missing \u2014 allows retransmitting only the lost segments (Selective Repeat). Combined with Fast Recovery, this handles multiple losses in one RTT much more efficiently than Reno."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tcp-cubic-rfc-8312-2008",children:"TCP CUBIC (RFC 8312, 2008)"}),"\n",(0,i.jsx)(n.p,{children:"CUBIC replaced the additive-increase with a cubic function \u2014 designed for high-bandwidth, long-delay networks (BDP \u226B 1 MB)."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Growth function:\n  W(t) = C \xd7 (t - K)\xb3 + W_max\n\n  where:\n    t = time since last congestion event\n    W_max = window size at last congestion event\n    K = time to grow back to W_max = \u221B(W_max \xd7 \u03B2 / C)\n    C = 0.4 (scaling constant)\n    \u03B2 = 0.7 (multiplicative decrease factor \u2014 less aggressive than Reno's 0.5)\n\nKey properties:\n  Slow initial increase (concave portion) \u2014 careful near W_max where last loss occurred\n  Fast increase in mid-range (far from W_max)\n  Slow again near W_max (probing cautiously)\n  Unlike Reno: growth rate is independent of RTT \u2014 fair to flows with different delays\n\nOn loss:\n  W_max = cwnd (save current window)\n  cwnd = cwnd \xd7 \u03B2 = cwnd \xd7 0.7 (multiplicative decrease \u2014 less drastic than /2)\n  ssthresh = cwnd\n  Enter Fast Recovery, then Congestion Avoidance with cubic growth\n\nStatus: Default in Linux since 2006; Windows since Windows 10; macOS uses its own variant\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tcp-bbr--bottleneck-bandwidth-and-rtt-google-2016",children:"TCP BBR \u2014 Bottleneck Bandwidth and RTT (Google, 2016)"}),"\n",(0,i.jsx)(n.p,{children:"BBR is a fundamentally different approach. Instead of reacting to packet loss (which indicates full queues, not full links), BBR models the actual bottleneck bandwidth and RTT."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"Key insight:\n  Loss-based algorithms like CUBIC react AFTER queues are full \u2014 they operate at peak loss rate\n  BBR models what the network can ACTUALLY deliver \u2014 targets high throughput with low latency\n  BBR explicitly probes for BtlBW (bottleneck bandwidth) and RTprop (minimum RTT)\n\nBBR's model:\n  BtlBW = measured delivery rate at bottleneck\n  RTprop = minimum RTT observed (no queuing delay = empty queue)\n  Optimal operating point = BtlBW \xd7 RTprop (the Bandwidth-Delay Product)\n\nBBR Phases:\n  STARTUP: exponential growth (like Slow Start) until delivery rate stops increasing\n  DRAIN: reduce pacing to drain any queue built during STARTUP\n  PROBE_BW: steady state, cycles pacing rate to probe for more bandwidth periodically\n  PROBE_RTT: periodically reduce cwnd to 4 packets to measure true minimum RTT (drain queues)\n\nKey BBR properties:\n  Pacing-based (not burst): sends packets evenly over time at the estimated BtlBW rate\n  NOT triggered by loss: retransmits only when necessary \u2014 doesn't overreact to AQM drops\n  Achieves high throughput AND low latency \u2014 fills the pipe without filling the queue\n  Unfairness: BBRv1 can be unfair to CUBIC flows (takes more bandwidth); BBRv2 improves this\n\nDeployment:\n  Google deployed BBR v1 in 2016; reported 2-25% throughput improvement, 75%+ latency reduction on congested paths\n  Available in Linux kernel 4.9+; widely used in CDNs, cloud providers\n  BBRv2 (2019+) addresses fairness issues\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"bandwidth-delay-product-bdp",children:"Bandwidth-Delay Product (BDP)"}),"\n",(0,i.jsx)(n.p,{children:'BDP is the volume of data that can be "in flight" on a network path at any time:'}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'BDP = Bandwidth (bits/sec) \xd7 RTT (seconds)\n\nExample: 1 Gbps WAN link, 100ms RTT\n  BDP = 1,000,000,000 \xd7 0.1 = 100,000,000 bits = ~12.5 MB\n\nImplication:\n  TCP window must be at least 12.5 MB to fully utilize this link\n  Without Window Scale option (max window 65,535 bytes = 64 KB), throughput is capped at:\n    64,000 bytes / 0.1 sec = 640 KB/s \u2014 only 0.5% of 1 Gbps capacity!\n  With Window Scale (scale factor 8): window up to 16 MB \u2192 can fill the pipe\n\n"Long Fat Network" (LFN) = high BDP \u2014 requires:\n  Large receive windows (Window Scale option)\n  SACK (for efficient loss recovery)\n  Timestamps (for RTT measurement and PAWS)\n  These three are RFC 7323 "TCP Extensions for High Performance"\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tcp-performance-diagnostics",children:"TCP Performance Diagnostics"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-bash",children:'# Linux: show TCP congestion control\nsysctl net.ipv4.tcp_congestion_control      # current algorithm\ncat /proc/sys/net.ipv4.tcp_available_congestion_control\nsysctl -w net.ipv4.tcp_congestion_control=bbr  # switch to BBR\n\n# Show socket statistics\nss -ti dst 8.8.8.8     # detailed TCP info for connection to 8.8.8.8\n# Output includes: cwnd, ssthresh, rtt, delivery_rate, retrans\n\n# iperf3 \u2014 measure TCP throughput\niperf3 -s                                   # server\niperf3 -c 10.0.0.1 -t 30 -P 4            # client: 30s test, 4 parallel streams\n\n# netstat \u2014 connection statistics\nnetstat -s | grep -i "tcp\\|retransmit\\|segment"\n\n# tcpdump \u2014 capture TCP headers\ntcpdump -i eth0 tcp and host 10.0.0.1 -w capture.pcap\n\n# Wireshark TCP stream analysis:\n# Statistics \u2192 TCP Stream Graphs \u2192 Time Sequence (shows cwnd growth)\n# Statistics \u2192 TCP Stream Graphs \u2192 Throughput\n# Statistics \u2192 TCP Stream Graphs \u2192 RTT (round-trip time over time)\n\n# Check for TCP buffer tuning (Linux)\nsysctl net.core.rmem_max         # max receive socket buffer\nsysctl net.core.wmem_max         # max send socket buffer\nsysctl net.ipv4.tcp_rmem         # min/default/max TCP receive buffer\nsysctl net.ipv4.tcp_wmem         # min/default/max TCP send buffer\n# For high-BDP networks, increase max buffers:\nsysctl -w net.core.rmem_max=134217728\nsysctl -w net.core.wmem_max=134217728\nsysctl -w net.ipv4.tcp_rmem="4096 87380 67108864"\nsysctl -w net.ipv4.tcp_wmem="4096 65536 67108864"\n'})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"ecn--explicit-congestion-notification-rfc-3168",children:"ECN \u2014 Explicit Congestion Notification (RFC 3168)"}),"\n",(0,i.jsx)(n.p,{children:"ECN allows routers to mark packets (instead of dropping them) when congestion begins \u2014 TCP gets an early warning before loss occurs."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"How it works:\n  1. TCP negotiates ECN capability in the SYN (ECE + CWR flags in SYN/SYN-ACK)\n  2. IP header ECN field: CE (Congestion Experienced) set by congested router\n  3. Receiver echoes CE to sender via ECE flag in ACK\n  4. Sender reacts as if loss occurred (halves cwnd) but WITHOUT actual packet drop\n  5. Sender sets CWR (Congestion Window Reduced) flag in next segment to acknowledge\n\nBenefit:\n  Reduces latency \u2014 react to congestion BEFORE queue fills and drops occur\n  Particularly valuable in data centers (DCB \u2014 Data Center Bridging, DCQCN, DCTCP)\n\nDCTCP (Data Center TCP, RFC 8257):\n  Uses multi-bit ECN marking (proportion of marked packets) to scale response\n  Keeps queue occupancy very low \u2192 microsecond latency in data center fabrics\n  Widely deployed in cloud provider networks (AWS, Azure, Google)\n"})}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"BBR is generally better than CUBIC for WAN connections with varying RTT and mild packet loss \u2014 but test in your environment; BBRv1 can hurt competing CUBIC flows."}),"\n",(0,i.jsx)(n.li,{children:"For maximum TCP performance on high-BDP links, ensure: Window Scale enabled, SACK enabled, TCP buffers tuned (Linux defaults are often too small)."}),"\n",(0,i.jsxs)(n.li,{children:["If TCP throughput is low on a high-speed link, check the effective window: ",(0,i.jsx)(n.code,{children:"throughput = window / RTT"}),". If limited, enable or increase Window Scale."]}),"\n",(0,i.jsx)(n.li,{children:"Asymmetric paths (send/receive going different routes) can cause duplicate ACKs and spurious retransmits \u2014 check routing when unexplained retransmission rate is high."}),"\n",(0,i.jsx)(n.li,{children:"SYN cookies mitigate SYN flood attacks at the cost of losing the ability to negotiate options (MSS, SACK, Window Scale don't work with SYN cookies) \u2014 acceptable trade-off for most servers."}),"\n"]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"TCP congestion control evolved from Van Jacobson's 1988 crisis fix through Tahoe \u2192 Reno \u2192 NewReno \u2192 SACK \u2192 CUBIC \u2192 BBR."}),"\n",(0,i.jsx)(n.li,{children:"Slow Start: exponential cwnd growth until ssthresh; Congestion Avoidance: linear (additive) growth afterward."}),"\n",(0,i.jsx)(n.li,{children:"Fast Retransmit + Fast Recovery: triple dupACK triggers immediate retransmit and halves cwnd (without dropping to 1 MSS like timeout does)."}),"\n",(0,i.jsx)(n.li,{children:"CUBIC uses a cubic growth function, independent of RTT \u2014 fairer across flows with different delays; default in Linux/Windows/macOS."}),"\n",(0,i.jsx)(n.li,{children:"BBR models the bottleneck bandwidth and RTT directly \u2014 achieves high throughput without filling queues, avoiding the latency penalty of loss-based algorithms."}),"\n",(0,i.jsx)(n.li,{children:"For Long Fat Networks: enable Window Scale, SACK, and Timestamps (RFC 7323), and tune OS TCP buffer sizes to match the path's BDP."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>a});var s=t(6540);let i={},o=s.createContext(i);function r(e){let n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);